const body = $json.body || $json;

// Extract all trip context fields sent by the packing checklist page
const destination     = body.destination     || '';
const tripType        = body.tripType        || '';
const days            = body.days            || '';
const startDate       = body.startDate       || '';
const endDate         = body.endDate         || '';
const travelPace      = body.travelPace      || '';
const budgetTier      = body.budgetTier      || '';
const travelers       = body.travelers       || '';
const activities      = Array.isArray(body.activities) ? body.activities.join(', ') : (body.activities || '');
const specialOccasion = body.specialOccasion || '';
const dietaryNeeds    = body.dietaryNeeds    || '';
const existingItems   = Array.isArray(body.existingItems) ? body.existingItems : [];

// Build a rich natural-language trip description
const tripParts = [
  destination     ? `Destination: ${destination}`            : null,
  tripType        ? `Trip type: ${tripType}`                 : null,
  days            ? `Duration: ${days} days`                 : null,
  startDate && endDate ? `Dates: ${startDate} to ${endDate}` : null,
  travelPace      ? `Travel pace: ${travelPace}`             : null,
  budgetTier      ? `Budget tier: ${budgetTier}`             : null,
  travelers       ? `Group: ${travelers}`                    : null,
  activities      ? `Activities planned: ${activities}`      : null,
  specialOccasion ? `Special occasion: ${specialOccasion}`   : null,
  dietaryNeeds    ? `Dietary needs: ${dietaryNeeds}`         : null,
].filter(Boolean);

const tripDesc = tripParts.length
  ? tripParts.join('\n')
  : 'General international leisure trip, 7 days';

const alreadyHave = existingItems.length
  ? `\n\nItems already on the packing list — do NOT suggest these: ${existingItems.slice(0, 40).join(', ')}`
  : '';

const prompt = `Create a packing suggestion for this trip:\n${tripDesc}${alreadyHave}`;

return [{ json: { prompt } }];

const raw = $node['OpenAI'].json.message?.content || $json.message?.content || '';

// Strip any accidental markdown fences
const clean = raw.replace(/^```[a-z]*\n?/gm, '').replace(/```\s*$/gm, '').trim();

let suggestions;
try {
  suggestions = JSON.parse(clean);
} catch(e) {
  // Try to extract JSON array if there's surrounding text
  const match = clean.match(/\[[\s\S]*\]/);
  if (!match) throw new Error('Could not parse AI packing response as JSON: ' + clean.slice(0, 100));
  suggestions = JSON.parse(match[0]);
}

if (!Array.isArray(suggestions) || !suggestions.length) {
  throw new Error('AI returned empty or invalid packing suggestions');
}

// Sanitise
const validated = suggestions
  .filter(cat => cat && cat.category && Array.isArray(cat.items) && cat.items.length)
  .map(cat => ({
    category: String(cat.category).trim(),
    items: cat.items
      .map(i => String(i).trim())
      .filter(i => i.length > 0)
      .slice(0, 15)
  }))
  .slice(0, 8);

return [{ json: { suggestions: validated } }];
